import configparser
import json
from pathlib import Path


def load_json(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def load_ini(path):
    parser = configparser.ConfigParser()
    parser.read(path, encoding="utf-8")
    return {section: dict(parser[section]) for section in parser.sections()}


def load(path, defaults=None):
    data = load_ini(path) if Path(path).suffix == ".ini" else load_json(path)
    merged = {section: dict(values) for section, values in (defaults or {}).items()}
    for section, values in data.items():
        merged.setdefault(section, {}).update(values)
    return merged

import configparser
import json
from pathlib import Path


def load_json(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def load_ini(path):
    parser = configparser.ConfigParser()
    parser.read(path, encoding="utf-8")
    return {section: dict(parser[section]) for section in parser.sections()}


def load(path, defaults=None):
    merged = {section: dict(values) for section, values in (defaults or {}).items()}
    for section, values in load_json(path).items():
        merged.setdefault(section, {}).update(values)
    return merged

